<span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E5C07B;">Authorized</span><span style="color:#D19A66;font-style:italic;"> permission</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&quot;order:delete&quot;</span><span style="color:#ABB2BF;">&gt;</span></span>
